const pick = (j, keys) => { for (const k of keys) if (j[k] !== undefined && j[k] !== '') return j[k]; return ''; };

function cleanDate(v) {
  const s = String(v).trim().split(' ')[0].split('T')[0];
  let r, d, m, y;
  if ((r = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/))) { y = r[1]; m = r[2]; d = r[3]; }
  else if ((r = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})$/))) { d = r[1]; m = r[2]; y = r[3]; }
  else return null;
  return y + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}

function cleanAmount(v) {
  // buang desimal ",00" / ".00" dulu supaya tidak jadi 100x lipat
  const s = String(v).replace(/[.,]\d{2}$/, '');
  return Number(s.replace(/[^0-9]/g, ''));
}

