const items = $input.all().map(i => i.json);
const internal = items.filter(i => i.source === 'INTERNAL');
const bank = items.filter(i => i.source === 'BANK');

// Map berbasis daftar agar transaksi kembar tidak salah cocok
const bankMap = new Map();
bank.forEach(b => {
  if (!bankMap.has(b.match_key)) bankMap.set(b.match_key, []);
  bankMap.get(b.match_key).push(b);
});

const results = [];
internal.forEach(r => {
  const list = bankMap.get(r.match_key);
  if (list && list.length) {
    list.pop();
    results.push({ ...r, status: 'Matched' });
  } else {
    results.push({ ...r, status: 'Missing in Bank' });
  }
});

bankMap.forEach(list => list.forEach(b => {
  results.push({ ...b, status: 'Unrecorded Internal' });
}));

return results.map(r => ({ json: r }));

const all = $input.all().map(i => i.json);
const diff = all.filter(i => i.status !== 'Matched');
const missing = diff.filter(i => i.status === 'Missing in Bank');
const unrec = diff.filter(i => i.status === 'Unrecorded Internal');
const fmt = r => '• ' + r.cleanDate + ' | Rp' + Number(r.cleanAmount).toLocaleString('id-ID');

let text = '⚠️ LAPORAN REKONSILIASI\n';
text += 'Total transaksi: ' + all.length + ' | Matched: ' + (all.length - diff.length) + ' | Selisih: ' + diff.length + '\n';
text += '\n❌ Missing in Bank (' + missing.length + '):\n' + (missing.map(fmt).join('\n') || '-');
text += '\n\n❓ Unrecorded Internal (' + unrec.length + '):\n' + (unrec.map(fmt).join('\n') || '-');

return [{ json: { diffCount: diff.length, text } }];
